requests.requestHelper:
apiFetch<{ allocation_plan: RawAllocationPlan; classifications: StrategicBucketClassification[] }>(
      `${root}/allocation-plans/${plan.id}/classifications`,
      {
        method: "PUT",
        token,
        headers: { ...versionHeaders(plan.revision_version), ...idempotencyHeaders(idempotencyKey) },
        body: JSON.stringify({
          classifications: classifications.flatMap((classification) => {
            const targetId =
              classification.target_id ?? classification.demand_id ?? classification.project_workspace_id;
            if (!targetId || !classification.bucket_code) return [];
            return [
              {
                target_type: classification.target_type ?? (classification.demand_id ? "DEMAND" : "PROJECT"),
                target_id: targetId,
                bucket_code: classification.bucket_code,
                rationale: classification.rationale ?? "",
              },
            ];
          }),
        }),
      }
    ).then

apiFetch<PortfolioReviewSession>(root, {
      method: "POST",
      token,
      headers: idempotencyHeaders(idempotencyKey),
      body: JSON.stringify(payload),
    }).then

apiFetch<PortfolioReviewSession>(`${root}/${session.id}`, {
      method: "PUT",
      token,
      headers: versionHeaders(session.revision_version),
      body: JSON.stringify(payload),
    }).then

requests.endpointTemplate:
(value) =>
      Array.isArray(value)
        ? { items: value, warnings: [] }
        : {
            ...value,
            items: (
              value.items ??
              ((value as unknown as Record<string, unknown>).points as PortfolioReviewTrends["items"] | undefined) ??
              []
            ).map((point) => ({
              ...point,
              review_id: numberValue(point.review_id, point.review_session_id),
              portfolio_count: numberValue(point.portfolio_count, point.portfolio_project_count),
              open_action_count: numberValue(point.open_action_count, point.open_action_count_at_close),
            })),
            warnings: strings(value.warnings),
          }

requests.requestHelper:
apiFetch<PortfolioReviewConclusion>(`${root}/${session.id}/conclusions`, {
      method: "POST",
      token,
      headers: versionHeaders(session.revision_version),
      body: JSON.stringify({
        conclusion_type: payload.conclusion_type,
        rationale: payload.rationale,
        conditions: payload.conditions ?? [],
      }),
    }).then

apiFetch<PortfolioReviewAction>(`${actionRoot}/${action.id}`, {
      method: "PUT",
      token,
      headers: versionHeaders(action.revision_version),
      body: JSON.stringify(payload),
    }).then
